def method_span(s,name):
    m=re.search(r'\b(?:public|private|protected|static|final|synchronized|native|abstract|strictfp|\s)+[\w<>\[\], ?]+\s+'+re.escape(name)+r'\s*\(',s)
    if not m:
        return None
    start=s.rfind('\n',0,m.start())+1
    brace=s.find('{',m.end())
    if brace<0:return None
    depth=0
    for i in range(brace,len(s)):
        c=s[i]
        if c=='{':depth+=1
        elif c=='}':
            depth-=1
            if depth==0:return start,i+1
    return None


def replace_method(s,name,new):
    span=method_span(s,name)
    if not span:return s
    a,b=span
    return s[:a]+new+s[b:]

