# Replace network method if present; it handles retry, 401 refresh, friendly errors, idempotency and loading.
post_new='''String post(JSONObject body,String auth){try{return rawPost(body,auth);}catch(Exception e){throw e instanceof RuntimeException?(RuntimeException)e:new RuntimeException(e);}}\n    String rawPost(JSONObject body,String auth)throws Exception{if(body==null)body=new JSONObject();String action=body.optString("action","");if(!body.has("request_id")&&java.util.Arrays.asList("add_charge","add_charge_finance","add_repair","add_repair_finance","manager_add_payment","approve_payment_finance","manager_finance_entry_create","request_subscription","register_manager").contains(action))body.put("request_id",java.util.UUID.randomUUID().toString());int tries=0;while(true){if(busyBar!=null&&Looper.myLooper()==Looper.getMainLooper())setBusy(true);else runOnUiThread(()->setBusy(true));HttpURLConnection c=null;try{URL u=new URL(API);c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(7000);c.setReadTimeout(9000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");if(auth!=null&&!auth.isEmpty())c.setRequestProperty("Authorization","Bearer "+auth);byte[] data=body.toString().getBytes(StandardCharsets.UTF_8);c.getOutputStream().write(data);int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)in=c.getInputStream();String out=new String(in.readAllBytes(),StandardCharsets.UTF_8);if(code==401&&auth!=null&&!"refresh_session".equals(action)&&securePrefs!=null){String rt=securePrefs.getString("refresh_token","");if(!rt.isEmpty()){JSONObject rb=new JSONObject().put("action","refresh_session").put("refresh_token",rt);String rr=rawPost(rb,null);JSONObject rj=new JSONObject(rr);String na=rj.optString("access_token",rj.optString("session",""));String nr=rj.optString("refresh_token",rt);if(!na.isEmpty()){session=na;securePrefs.edit().putString("session",na).putString("refresh_token",nr).apply();return rawPost(body,na);}}}if(code>=500&&tries<2){tries++;continue;}if(code>=400)throw new RuntimeException(new JSONObject(out).optString("error","خطای سرور"));return out;}catch(java.net.UnknownHostException|java.net.ConnectException e){if(tries<2){tries++;continue;}throw new RuntimeException("اینترنت در دسترس نیست");}catch(java.net.SocketTimeoutException e){if(tries<1){tries++;continue;}throw new RuntimeException("پاسخ سرور دیر دریافت شد. دوباره تلاش کنید.");}finally{if(c!=null)c.disconnect();runOnUiThread(()->setBusy(false));}}}\n    void setBusy(boolean v){if(busyBar!=null)busyBar.setVisibility(v?View.VISIBLE:View.GONE);if(root!=null){java.util.ArrayDeque<View> q=new java.util.ArrayDeque<>();q.add(root);while(!q.isEmpty()){View x=q.remove();if(x instanceof Button)x.setEnabled(!v);if(x instanceof ViewGroup){ViewGroup g=(ViewGroup)x;for(int i=0;i<g.getChildCount();i++)q.add(g.getChildAt(i));}}}}\n    String friendly(Exception e){String m=e==null?"":String.valueOf(e.getMessage());if(m.contains("UnknownHost")||m.contains("internet")||m.contains("اینترنت"))return "اینترنت در دسترس نیست";if(m.contains("timeout")||m.contains("Timeout"))return "ارتباط با سرور زمان‌بر شد. دوباره تلاش کنید.";return m.isEmpty()?"خطایی رخ داد. دوباره تلاش کنید.":m;}'''
s=replace_method(s,'post',post_new)

